def storage_class_for_age(age_days):
    if age_days < 30:
        return "STANDARD"
    if age_days < 90:
        return "NEARLINE"
    if age_days < 365:
        return "COLDLINE"
    return "ARCHIVE"


objects = [
    ("access-log-2026-09-01.json", 10),
    ("quarterly-report-q1.pdf", 95),
    ("user-upload-avatar.png", 40),
    ("compliance-archive-2023.tar", 900),
]
for name, age in objects:
    print(f"{name}: age={age}d -> {storage_class_for_age(age)}")
